package com.optarena.app;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.web.servlet.MockMvc;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class OrderEndpointHiddenTest {

    @Autowired
    private MockMvc mvc;

    private void order(String body, String tier, int fee) throws Exception {
        mvc.perform(post("/orders").contentType("application/json").content(body))
           .andExpect(status().isOk())
           .andExpect(jsonPath("$.tier").value(tier))
           .andExpect(jsonPath("$.fee").value(fee));
    }

    @Test
    void standardOrder() throws Exception {
        order("{\"items\": 3, \"priority\": false}", "standard", 10);
    }

    @Test
    void bulkBoundary() throws Exception {
        order("{\"items\": 10, \"priority\": false}", "bulk", 5);
    }

    @Test
    void priorityIsExpress() throws Exception {
        order("{\"items\": 2, \"priority\": true}", "express", 20);
    }

    @Test
    void priorityBeatsBulk() throws Exception {
        order("{\"items\": 50, \"priority\": true}", "express", 20);
    }

    @Test
    void echoesItems() throws Exception {
        mvc.perform(post("/orders").contentType("application/json").content("{\"items\": 7, \"priority\": false}"))
           .andExpect(jsonPath("$.items").value(7));
    }

    @Test
    void healthStillWorks() throws Exception {
        mvc.perform(get("/health")).andExpect(status().isOk()).andExpect(content().string("ok"));
    }
}

