package com.optarena.app;

import java.util.Map;

import org.springframework.stereotype.Service;

@Service
public class OrderService {

    public Map<String, Object> classify(int items, boolean priority) {
        String tier;
        if (priority) {
            tier = "express";
        } else if (items >= 10) {
            tier = "bulk";
        } else {
            tier = "standard";
        }
        int fee = switch (tier) {
            case "express" -> 20;
            case "bulk" -> 5;
            default -> 10;
        };
        return Map.of("tier", tier, "fee", fee);
    }
}

