@Service
public class OrderService {

    public Map<String, Object> classify(int items, boolean priority) {
        // BUG: priority is ignored, so priority orders never become express
        String tier = items >= 10 ? "bulk" : "standard";
        int fee = tier.equals("bulk") ? 5 : 10;
        return Map.of("tier", tier, "fee", fee);
    }
}

